using namespace libprojectM::MilkdropPreset;
using namespace libprojectM::Renderer;
using RGBA=std::array<float,4>;
static void Check(bool v,const std::string&m){if(!v)throw std::runtime_error(m);}
#include "shape_attribute_probe.hpp"
using XY=std::array<float,2>;
struct Capture{GLenum primitive{};GLint target{};bool instanced{};std::vector<XY>a,b;std::vector<RGBA>rgba,rgbaB;XY passOffset{};};
static std::vector<Capture> captured;
static PFNGLDRAWARRAYSPROC originalArrays{};static PFNGLDRAWARRAYSINSTANCEDPROC originalInstanced{};
static GLint Target(){GLint value{};glGetIntegerv(GL_DRAW_FRAMEBUFFER_BINDING,&value);return value;}
static XY Position(const Attribute&attr,size_t row){return{attr.Component(row,0),attr.Component(row,1)};}
static void ObserveArrays(GLenum mode,GLint first,GLsizei count){Capture c;c.primitive=mode;c.target=Target();Attribute p(0),rgba(1);for(int i=0;i<count;++i){c.a.push_back(Position(p,first+i));c.rgba.push_back(rgba.Color(first+i));}captured.push_back(std::move(c));originalArrays(mode,first,count);}
static void ObserveInstanced(GLenum mode,GLint first,GLsizei count,GLsizei instances){Check(mode==GL_TRIANGLE_STRIP&&first==0&&count==4,"actual Native quad contract");Capture c;c.primitive=mode;c.target=Target();c.instanced=true;Attribute a(1),b(2),rgbaA(4),rgbaB(5);Check(a.divisor==1&&rgbaA.divisor==1,"instance attribute divisor");GLint program{};glGetIntegerv(GL_CURRENT_PROGRAM,&program);const GLint loc=glGetUniformLocation(program,"pass_offset");Check(loc>=0,"actual line pass offset uniform");glGetUniformfv(program,loc,c.passOffset.data());for(int i=0;i<instances;++i){c.a.push_back(Position(a,i));c.b.push_back(Position(b,i));c.rgba.push_back(rgbaA.Color(i));c.rgbaB.push_back(rgbaB.Color(i));}captured.push_back(std::move(c));originalInstanced(mode,first,count,instances);}
struct Hook{Hook(){captured.clear();originalArrays=glad_glDrawArrays;originalInstanced=glad_glDrawArraysInstanced;glad_glDrawArrays=ObserveArrays;glad_glDrawArraysInstanced=ObserveInstanced;}~Hook(){glad_glDrawArrays=originalArrays;glad_glDrawArraysInstanced=originalInstanced;}};
static bool Near(float a,float b){return std::abs(a-b)<3e-6f;}
static void Equal(XY a,XY b,const char*label){Check(Near(a[0],b[0])&&Near(a[1],b[1]),label);}
static int Identity(const RGBA&c){if(c[0]>.5f)return 0;if(c[1]>.5f)return 1;if(c[2]>.5f)return 2;throw std::runtime_error("instance colour identity");}
static void Palette(const RGBA&c,int id){for(int k=0;k<3;++k)Check(Near(c[k],k==id?1.f:0.f),"per-instance float RGB retained");Check(Near(c[3],.2f+.1f*id),"per-instance fractional alpha retained, no byte packing");}
static XY Corner(int id,int j,bool overlap){constexpr float pi=3.141592653589793f;const float center=overlap?0.f:-.6f+.6f*id;const float angle=float(j)/4*pi*2+pi*.25f;return{center+.12f*cosf(angle),.12f*sinf(angle)};}
static void Three(ShaderCache&cache,const std::string&expr,const std::array<bool,3>&thick,int saved,bool replay,bool overlap=false,bool opaque=false,bool zeroBorder=false){
 PresetState state;std::ostringstream text;text<<"shapecode_0_enabled=1\nshapecode_0_sides=4\nshapecode_0_num_inst=3\nshapecode_0_textured=0\nshapecode_0_thickOutline="<<saved<<"\nshapecode_0_rad=.12\n"
 <<"shape_0_init1=reg02+=1;\nshape_0_per_frame1="<<expr<<"x="<<(overlap?".5":".2+.3*instance")<<";y=.5;a="<<(opaque?1:0)<<";a2=a;border_r=equal(instance,0);border_g=equal(instance,1);border_b=equal(instance,2);border_a="<<(zeroBorder?"0":".2+.1*instance")<<";reg00+=1;\n";
 std::istringstream input(text.str());PresetFileParser parser;Check(parser.Read(input),"actual parser");state.Initialize(parser);auto&rc=state.renderContext;rc.shaderCache=&cache;rc.viewportSizeX=rc.viewportSizeY=128;rc.lineReferenceWidth=rc.lineReferenceHeight=64;rc.aspectX=rc.aspectY=rc.invAspectX=rc.invAspectY=1;state.LoadShaders();Check(state.lineRenderer.Usable(),"actual Native line program");CustomShape shape(state);shape.Initialize(parser,0);std::vector<std::string>warnings;shape.CompileCodeAndRunInitExpressions(warnings);Check(warnings.empty(),"actual shape init/frame compile");
 Framebuffer canvas(1),native(1);canvas.CreateColorAttachment(0,0,GL_RGBA8,GL_RGBA,GL_UNSIGNED_BYTE);native.CreateColorAttachment(0,0,GL_RGBA8,GL_RGBA,GL_UNSIGNED_BYTE);canvas.SetSize(64,64);native.SetSize(128,128);GeometryTargets targets(state,canvas,0,64,64,{},native,0);
 native.Bind(0);const GLint nativeId=Target();targets.Authored();const GLint canvasId=Target();
 for(int frame=0;frame<2;++frame){targets.Authored();{Hook hook;shape.Draw(replay?&targets:nullptr);}Check(glGetError()==GL_NO_ERROR,"actual draw GL error");Check(state.globalRegisters[0]==3*(frame+1)&&state.globalRegisters[2]==1,"one evaluation per instance, init once, no Native reevaluation");std::array<int,3>loops{},segments{};int fills=0,nativeCalls=0;
  for(const auto&c:captured){if(c.primitive==GL_TRIANGLE_FAN){++fills;continue;}if(!c.instanced){Check(c.target==canvasId&&c.primitive==GL_LINE_LOOP&&c.a.size()==4,"actual authored outline");const int id=Identity(c.rgba[0]);Palette(c.rgba[0],id);const int pass=loops[id]++;const auto offset=PassOffsetFor(LineStyleFor(LineKind::ShapeBorder,thick[id],1,64,64),pass);for(int j=0;j<4;++j){auto expected=Corner(id,j,overlap);expected[0]+=offset.x;expected[1]+=offset.y;Equal(c.a[j],expected,"authored current-I23 per-pass positions");}}
   else{++nativeCalls;Check(replay&&c.target==nativeId,"owned Native replay target");for(size_t j=0;j<c.a.size();++j){const int id=Identity(c.rgba[j]);Check(Identity(c.rgbaB[j])==id,"no false inter-outline connector");Palette(c.rgba[j],id);Palette(c.rgbaB[j],id);const int pass=segments[id]/4,edge=segments[id]%4;++segments[id];Equal(c.a[j],Corner(id,edge,overlap),"Native prepared A position");Equal(c.b[j],Corner(id,(edge+1)%4,overlap),"Native prepared B position");const auto offset=PassOffsetFor(LineStyleFor(LineKind::ShapeBorder,thick[id],2,128,128),pass);Equal(c.passOffset,{offset.x,offset.y},"Native retained I23 offsets, not original1px restoration");}}
  }
  int totalPasses=0;for(int id=0;id<3;++id){const int passes=zeroBorder?0:thick[id]?4:1;totalPasses+=passes;Check(loops[id]==passes,"evaluated authored instance style");Check(segments[id]==(replay?passes*4:0),"evaluated Native instance style");}Check(fills==3*(replay?2:1),"retain fill calls, including transparent fills");const bool canGroup=thick[0]&&thick[1]&&thick[2]&&!overlap&&!opaque&&!zeroBorder;Check(nativeCalls==(replay?(canGroup?4:totalPasses):0),"safe grouping/native call count");
 }
}
// Independent original49-instance source trace at frozen q2=q3=0,q32=1.
struct OriginalInstance{float x,y,rad;bool thick;float alpha;};
static OriginalInstance Original49(int instance){const int nx=instance%6,ny=instance/6;OriginalInstance o{.5f+(nx-3)/4.f,.5f+(ny-3)/4.f,.04f,false,1};if(instance>35&&instance<38)o={.5f-.47f*(instance%2-.5f),.5f,.06f,false,1};else if(instance>=38&&instance<45)o={.5f,.5f-.47f*((instance/3)%2-.5f),.06f,false,1};else if(instance>=45)o={.5f+((instance/2)%2-.5f)*.5f,.5f+(instance%2-.5f)*.5f,.04f,true,0};return o;}
static void City(ShaderCache&cache,const char*path){PresetFileParser parser;Check(parser.Read(path),"exact original parser");PresetState state;state.Initialize(parser);state.frameQVariables.fill(0);state.frameQVariables[31]=1;state.customShapePerFrameCode[0]+="reg00+=1;";auto&rc=state.renderContext;rc.shaderCache=&cache;rc.viewportSizeX=rc.viewportSizeY=128;rc.lineReferenceWidth=rc.lineReferenceHeight=64;rc.aspectX=rc.aspectY=rc.invAspectX=rc.invAspectY=1;state.LoadShaders();CustomShape shape(state);shape.Initialize(parser,0);std::vector<std::string>warnings;shape.CompileCodeAndRunInitExpressions(warnings);Check(warnings.empty(),"exact49 shape compilation");Framebuffer canvas(1),native(1);canvas.CreateColorAttachment(0,0,GL_RGBA8,GL_RGBA,GL_UNSIGNED_BYTE);native.CreateColorAttachment(0,0,GL_RGBA8,GL_RGBA,GL_UNSIGNED_BYTE);canvas.SetSize(64,64);native.SetSize(128,128);GeometryTargets targets(state,canvas,0,64,64,{},native,0);native.Bind(0);const int nativeId=Target();targets.Authored();const int canvasId=Target();{Hook hook;shape.Draw(&targets);}int authoredFills=0,nativeFills=0,loops=0,quads=0,segmentPasses=0;for(const auto&c:captured){if(c.primitive==GL_TRIANGLE_FAN){const int instance=c.target==canvasId?authoredFills++:nativeFills++;Check(instance<49,"exact49 fill count");const auto expected=Original49(instance);Equal(c.a[0],{expected.x*2-1,expected.y*-2+1},"exact49 source instance center");Check(Near(c.rgba[0][3],expected.alpha),"exact49 per-instance fill alpha");}else if(c.instanced){Check(c.target==nativeId,"city Native target");++quads;segmentPasses+=int(c.a.size());for(const auto&rgba:c.rgba)Check(Near(rgba[3],.2f),"city floating border alpha retained");}else{++loops;Check(c.target==canvasId,"city authored target");}}
 Check(authoredFills==49&&nativeFills==49&&loops==61&&quads==49&&segmentPasses==244,"original49 pass trace and grouped Native49-call contract");Check(state.globalRegisters[0]==49,"no last-instance reuse or Native equation replay");Check(glGetError()==GL_NO_ERROR,"exact49 GL state");std::cout<<"city original49 source trace: authored61, Native49calls/244segment instances, fills49+49\n";}
int main(int argc,char**argv){try{GLContext gl;ShaderCache cache;for(bool replay:{false,true}){Three(cache,"thick=equal(instance,1);",{false,true,false},0,replay);Three(cache,"thick=1;",{true,true,true},0,replay);Three(cache,"thick=-1;",{true,true,true},0,replay);Three(cache,"thick=.5;",{false,false,false},1,replay);Three(cache,"thick=-.5;",{false,false,false},1,replay);Three(cache,"thick=0;",{false,false,false},1,replay);Three(cache,"",{true,true,true},1,replay);Three(cache,"",{false,false,false},-1,replay);Three(cache,"thick=1;",{true,true,true},0,replay,true);Three(cache,"thick=1;",{true,true,true},0,replay,false,true);Three(cache,"thick=1;",{true,true,true},0,replay,false,false,true);}if(argc>1)City(cache,argv[1]);std::cout<<"actual per-instance thick/positions/alpha/group/replay controls passed\n";}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}return 0;}
